/**
 * CredentialVault - Secure storage for API keys using client-side encryption
 * 
 * Security Model:
 * - Master key stored in localStorage (MVP limitation - should use WebAuthn/Secure Enclave in production)
 * - AES-256-GCM encryption for all stored credentials
 * - Unique IV (Initialization Vector) per encryption operation
 * - Decrypted values only in memory, never logged or persisted
 * 
 * MVP Limitations:
 * - Master key in localStorage is vulnerable to XSS attacks
 * - No key rotation mechanism
 * - No biometric authentication
 */

const ENCRYPTION_ALGORITHM = 'AES-GCM';
const KEY_LENGTH = 256;
const MASTER_KEY_STORAGE = 'via-gent-master-key';
const IV_LENGTH = 12; // Recommended 12 bytes for GCM

export class CredentialVault {
  private masterKey: CryptoKey | null = null;
  private encoder = new TextEncoder();
  private decoder = new TextDecoder();

  /**
   * Initialize the credential vault
   * Loads or generates the master encryption key
   */
  async initialize(): Promise<void> {
    const storedKey = localStorage.getItem(MASTER_KEY_STORAGE);

    if (storedKey) {
      // Load existing master key from localStorage
      const keyData = JSON.parse(storedKey) as JsonWebKey;
      this.masterKey = await crypto.subtle.importKey(
        'jwk',
        keyData,
        { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
        false,
        ['encrypt', 'decrypt']
      );
    } else {
      // Generate new master key
      this.masterKey = await crypto.subtle.generateKey(
        { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
        true,
        ['encrypt', 'decrypt']
      );

      // Store master key in localStorage (MVP limitation)
      const exportedKey = await crypto.subtle.exportKey('jwk', this.masterKey);
      localStorage.setItem(MASTER_KEY_STORAGE, JSON.stringify(exportedKey));
    }
  }

  /**
   * Store encrypted credentials for a provider
   * @param providerId - Unique identifier for the AI provider
   * @param apiKey - The API key to encrypt and store
   */
  async storeCredentials(providerId: string, apiKey: string): Promise<void> {
    if (!this.masterKey) {
      throw new Error('CredentialVault not initialized. Call initialize() first.');
    }

    // Generate unique IV for this encryption operation
    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));

    // Encrypt the API key
    const encrypted = await crypto.subtle.encrypt(
      { name: ENCRYPTION_ALGORITHM, iv },
      this.masterKey,
      this.encoder.encode(apiKey)
    );

    // Convert to Base64 for storage
    const encryptedBase64 = btoa(String.fromCharCode(...new Uint8Array(encrypted)));
    const ivBase64 = btoa(String.fromCharCode(...iv));

    // Store in IndexedDB via Dexie
    await db.credentials.put({
      providerId,
      encrypted: encryptedBase64,
      iv: ivBase64,
      createdAt: new Date(),
    });
  }

  /**
   * Retrieve and decrypt credentials for a provider
   * @param providerId - Unique identifier for the AI provider
   * @returns The decrypted API key, or null if not found
   */
  async getCredentials(providerId: string): Promise<string | null> {
    if (!this.masterKey) {
      throw new Error('CredentialVault not initialized. Call initialize() first.');
    }

    const record = await db.credentials.get(providerId);

    if (!record) {
      return null;
    }

    // Decode Base64 to Uint8Array
    const encrypted = Uint8Array.from(atob(record.encrypted), c => c.charCodeAt(0));
    const iv = Uint8Array.from(atob(record.iv), c => c.charCodeAt(0));

    // Decrypt the API key
    const decrypted = await crypto.subtle.decrypt(
      { name: ENCRYPTION_ALGORITHM, iv },
      this.masterKey,
      encrypted
    );

    // Return decrypted value (only in memory)
    return this.decoder.decode(decrypted);
  }

  /**
   * Delete credentials for a provider
   * @param providerId - Unique identifier for the AI provider
   */
  async deleteCredentials(providerId: string): Promise<void> {
    await db.credentials.delete(providerId);
  }

  /**
   * Check if credentials exist for a provider
   * @param providerId - Unique identifier for the AI provider
   */
  async hasCredentials(providerId: string): Promise<boolean> {
    const record = await db.credentials.get(providerId);
    return record !== undefined;
  }

  /**
   * List all provider IDs with stored credentials
   */
  async listProviders(): Promise<string[]> {
    return await db.credentials.toCollection().primaryKeys();
  }
}

// Singleton instance
export const credentialVault = new CredentialVault();

/**
 * Dexie Database Schema
 * 
 * Version History:
 * - v1: Initial schema with projects and conversations
 * - v2: Added workspaces table
 * - v3: Added ideSettings table
 * - v4: Added credentials table for encrypted API keys
 */

import Dexie, { Table } from 'dexie';

// Credential record interface
export interface CredentialRecord {
  providerId: string;         // Primary key: unique provider identifier
  encrypted: string;          // Base64-encoded encrypted API key
  iv: string;                 // Base64-encoded initialization vector
  createdAt: Date;            // Timestamp when credential was stored
}

// Database class
class ViaGentDatabase extends Dexie {
  credentials!: Table<CredentialRecord, string>;

  constructor() {
    super('via-gent-persistence');

    // Version 4: Added credentials table
    this.version(4).stores({
      credentials: 'providerId, createdAt',
    });
  }
}

// Singleton instance
export const db = new ViaGentDatabase();

architecture_patterns.pattern:
Use singleton instance for CredentialVault to ensure single master key in memory.
Pattern: export const credentialVault = new CredentialVault();
Benefits: Consistent state, prevents multiple key instances, easier to manage lifecycle.
